mapper.select:
SELECT *
FROM risk_alerts
WHERE publish_status IN ('PENDING', 'FAILED')
AND created_at < #{before}
AND publish_attempts < #{maxAttempts}
ORDER BY id ASC
LIMIT #{limit}

mapper.update:
UPDATE risk_alerts
SET publish_attempts = publish_attempts + 1
WHERE alert_id = #{alertId}

UPDATE risk_alerts
SET publish_status = #{status}
WHERE alert_id = #{alertId}

mapper.select:
SELECT COUNT(*)
FROM risk_alerts
WHERE user_id = #{userId}
AND source = #{source}
AND created_at >= #{since}
